package local.atmospherevisual;

import me.cryo.zombierool.gameplay.*;
import me.cryo.zombierool.client.MapAtmosphereClient;
import net.minecraft.client.Minecraft;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.core.*;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.fml.common.Mod;
import java.nio.file.Path;

@Mod("atmospherevisual")
public final class MapAtmosphereVisualTest {
    private boolean requested,done;private int age,checks,reloads,beforeWorldReloads;private volatile String failure;
    private com.mojang.blaze3d.platform.NativeImage baseline,sky,handBaseline,noHand,fogImage;
    public MapAtmosphereVisualTest(){net.minecraftforge.fml.javafmlmod.FMLJavaModLoadingContext.get().getModEventBus().addListener((net.minecraftforge.client.event.RegisterClientReloadListenersEvent event)->event.registerReloadListener((net.minecraft.server.packs.resources.ResourceManagerReloadListener)manager->reloads++));MinecraftForge.EVENT_BUS.addListener(this::tick);MinecraftForge.EVENT_BUS.addListener(this::hud);}
    private void check(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;System.out.println("ATMOSPHERE VISUAL CHECK: "+text);}
    private void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> task){var mc=Minecraft.getInstance();mc.getSingleplayerServer().execute(()->{try{task.accept(mc.getSingleplayerServer().getPlayerList().getPlayers().get(0));}catch(Throwable t){t.printStackTrace();failure=t.toString();}});}
    private com.mojang.blaze3d.platform.NativeImage shot(String name)throws Exception{var mc=Minecraft.getInstance();var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget());image.writeToFile(Path.of(System.getProperty("atmosphere.output")+"/"+name+".png"));return image;}
    private void hud(net.minecraftforge.client.event.RenderGuiEvent.Post e){e.getGuiGraphics().fill(5,5,25,25,0xFFFF0000);}
    private CompoundTag neutral(){var n=MapAtmosphere.defaults();n.putBoolean("enabled",true);return MapAtmosphere.sanitize(n);}
    private void tick(TickEvent.ClientTickEvent e){
        if(done||e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;
        try{
            if(failure!=null)throw new AssertionError(failure);
            if(!requested){requested=true;mc.options.pauseOnLostFocus=false;mc.options.fov().set(70);org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().getWindow());beforeWorldReloads=reloads;mc.createWorldOpenFlows().loadLevel(mc.screen,"AtmosphereFixture");return;}
            if(mc.screen instanceof net.minecraft.client.gui.screens.DisconnectedScreen){for(var f:mc.screen.getClass().getDeclaredFields())if(net.minecraft.network.chat.Component.class.isAssignableFrom(f.getType())){f.setAccessible(true);System.out.println("ATMOSPHERE DISCONNECT: "+f.get(mc.screen));}throw new AssertionError("Client disconnected while loading atmosphere fixture");}
            if(mc.level==null||mc.player==null||mc.isPaused())return;age++;
            if(age==40)server(p->{p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.teleportTo(p.serverLevel(),.5,65,28.5,180,-14);MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),MapAtmosphere.defaults());});
            if(age==41&&Boolean.getBoolean("atmosphere.listOnly"))age=239;
            if(age==70){check(reloads==beforeWorldReloads,"Entering the map performs no resource-pack reload");me.cryo.zombierool.client.ClientEnvironmentEffects.setFogPreset("none",0,0,0,1,512);baseline=shot("baseline");server(p->MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),neutral()));}
            if(age==110){check(MapAtmosphereClient.settings().getBoolean("enabled"),"Persistent atmosphere synchronizes from server");check(mc.getResourceManager().getResource(new net.minecraft.resources.ResourceLocation(MapAtmosphereClient.settings().getString("skyTexture"))).isPresent(),"Original six-face sky atlas is available");sky=shot("custom-sky");long difference=0;for(int y=30;y<sky.getHeight()/3;y+=9)for(int x=50;x<sky.getWidth()-50;x+=9)if(sky.getPixelRGBA(x,y)!=baseline.getPixelRGBA(x,y))difference++;check(difference>50,"Custom sky changes actual sky pixels in finalized world framebuffer");int a=baseline.getPixelRGBA(baseline.getWidth()/2,baseline.getHeight()-140),b=sky.getPixelRGBA(sky.getWidth()/2,sky.getHeight()-140);System.out.println("ATMOSPHERE PIXEL: baseline="+Integer.toHexString(a)+" custom="+Integer.toHexString(b));check(Math.abs((a&255)-(b&255))<30&&Math.abs((a>>8&255)-(b>>8&255))<30&&Math.abs((a>>16&255)-(b>>16&255))<30,"Sky replacement preserves foreground terrain colors at neutral grading");}
            if(age==115)mc.options.hideGui=true;
            if(age==125){try(var image=shot("hidden-hud")){int a=sky.getPixelRGBA(800,100),b=image.getPixelRGBA(800,100);check(Math.abs((a&255)-(b&255))<25&&Math.abs((a>>8&255)-(b>>8&255))<25,"Custom sky remains active with the HUD hidden by F1");}mc.options.hideGui=false;server(p->{var n=neutral();n.putDouble("skyYaw",90);MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),n);});}
            if(age==145){try(var image=shot("sky-rotated")){check(image.getPixelRGBA(800,100)!=sky.getPixelRGBA(800,100),"Yaw control rotates the cubemap");}server(p->{var n=neutral();n.putDouble("saturation",0);MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),n);});}
            if(age==180){try(var image=shot("grayscale")){int color=image.getPixelRGBA(800,100),r=color&255,g=color>>8&255,b=color>>16&255;check(Math.abs(r-g)<=2&&Math.abs(g-b)<=2,"Color grading desaturates the world and custom sky");int hud=image.getPixelRGBA(15,45);check((hud&255)>240&&(hud>>8&255)<10,"World grading leaves the HUD red test marker unchanged");}server(p->{var n=MapAtmosphere.ashfall();n.putDouble("vignette",.8);n.putDouble("dirt",.4);MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),n);});}
            if(age==190){check(MapAtmosphereClient.skyIds().contains("zombierool:world_sky/fixture"),"Map-local sky texture arrives through dynamic transport without reloading packs");check(me.cryo.zombierool.client.DynamicSoundLoader.customAudioIds().contains("zombierool:custom/fixture"),"Map-local ambience is discoverable after dynamic audio synchronization");server(p->{var n=MapAtmosphere.get(p.serverLevel()).settings();n.putString("skyTexture","zombierool:world_sky/fixture");MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),n);});}
            if(age==205){check(MapAtmosphereClient.settings().getString("skyTexture").equals("zombierool:world_sky/fixture"),"Dynamically loaded map skies can be selected like bundled skies");}
            if(age==220){try(var ignored=shot("vignette-dirt")){}check(MapAtmosphereClient.settings().getDouble("vignette")==.8,"Vignette, dirt and color controls synchronize");for(String id:MapAtmosphere.soundIds())check(mc.getSoundManager().getSoundEvent(new net.minecraft.resources.ResourceLocation(id))!=null,"Bundled preset sound resolves: "+id);for(String id:MapAtmosphere.presetIds())if(!id.equals("none"))check(mc.getResourceManager().getResource(new net.minecraft.resources.ResourceLocation(MapAtmosphere.preset(id).getString("skyTexture"))).isPresent(),"Preset sky resolves: "+id);server(p->MapAtmosphere.get(p.serverLevel()).trigger(p.serverLevel(),"thunder"));}
            if(age==240){var n=MapAtmosphereClient.settings();mc.setScreen(new me.cryo.zombierool.client.gui.MapAtmosphereScreen(n,null));}
            if(age==250){check(mc.screen instanceof me.cryo.zombierool.client.gui.MapAtmosphereScreen,"Map maker atmosphere editor opens");for(var child:mc.screen.children())if(child instanceof net.minecraft.client.gui.components.AbstractWidget w)check(w.getY()>=0&&w.getY()+w.getHeight()<=mc.screen.height,"Editor control fits the viewport");try(var ignored=shot("editor")){}var screen=mc.screen;for(var child:java.util.List.copyOf(screen.children()))if(child instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Ambiances")){b.onPress();break;}try(var ignored=shot("audio-editor")){}for(var child:java.util.List.copyOf(screen.children()))if(child instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().startsWith("Ajouter un son")){b.onPress();break;}check(mc.screen!=screen,"Add a sound opens a searchable catalogue");for(var child:mc.screen.children())if(child instanceof net.minecraft.client.gui.components.AbstractWidget w)check(w.getY()>=0&&w.getY()+w.getHeight()<=mc.screen.height,"Sound picker control fits the viewport");try(var ignored=shot("sound-picker")){}boolean scrollable=false;for(var child:mc.screen.children())if(child instanceof net.minecraft.client.gui.components.ObjectSelectionList<?> list){list.mouseScrolled(mc.screen.width/2.,110,-3);scrollable=list.getScrollAmount()>0;}check(scrollable,"The sound catalogue scrolls with the mouse wheel instead of cycling a button");}
            if(age==252)for(var child:mc.screen.children())if(child instanceof net.minecraft.client.gui.components.EditBox box)box.setValue("fixture");
            if(age==254){boolean selected=false;for(var child:java.util.List.copyOf(mc.screen.children()))if(child instanceof net.minecraft.client.gui.components.ObjectSelectionList<?> list){check(list.children().size()==1,"Search filters the catalogue to the matching map-local sound");list.children().get(0).mouseClicked(mc.screen.width/2.-150,80,0);selected=true;break;}check(selected&&mc.screen instanceof me.cryo.zombierool.client.gui.MapAtmosphereScreen,"Clicking a sound row adds it and returns to its editor");}
            if(age==256){boolean opened=false;for(var child:java.util.List.copyOf(mc.screen.children()))if(child instanceof net.minecraft.client.gui.components.Button button&&button.getMessage().getString().startsWith("ambience_")){button.onPress();opened=true;break;}check(opened&&!(mc.screen instanceof me.cryo.zombierool.client.gui.MapAtmosphereScreen),"Existing ambience sources are selected from a list instead of a cycle button");try(var ignored=shot("source-list")){}mc.screen.onClose();}
            if(age==258){mc.screen.onClose();if(Boolean.getBoolean("atmosphere.listOnly")){done=true;System.out.println("ATMOSPHERE VISUAL PASS: "+checks+" sound-list checks");mc.stop();}}
            if(age==260){mc.setScreen(new me.cryo.zombierool.client.gui.MapAtmosphereScreen(MapAtmosphere.ashfall(),null));for(var child:java.util.List.copyOf(mc.screen.children()))if(child instanceof net.minecraft.client.gui.components.Button button&&button.getMessage().getString().endsWith(" ▾")){button.onPress();break;}for(var child:java.util.List.copyOf(mc.screen.children()))if(child instanceof net.minecraft.client.gui.components.ObjectSelectionList<?> list)for(var row:list.children())if(row.getNarration().getString().equals("Moon")){row.mouseClicked(180,80,0);break;}check(MapAtmosphereClient.settings().getString("presetId").equals("moon"),"Selecting a preset in the editor immediately changes the real client atmosphere");check(MapAtmosphereClient.settings().getString("skyTexture").contains("lunar_sky"),"Preset selection replaces the sky resource without a command");for(var child:java.util.List.copyOf(mc.screen.children()))if(child instanceof net.minecraft.client.gui.components.Button button&&button.getMessage().getString().equals("Terminé")){button.onPress();break;}}
            if(age==275)server(p->check(MapAtmosphere.get(p.serverLevel()).settings().getString("presetId").equals("moon"),"Done persists the editor-selected preset on the server"));
            if(age==280){var n=MapAtmosphere.source("test","zombierool:ambient_distant_alarm",false,false,0,80,0,1,100,10,20);check(MapAtmosphereClient.gain(n,0,false)==1&&MapAtmosphereClient.gain(n,100,false)==0,"Distance attenuation reaches full volume near source and silence at radius");check(MapAtmosphereClient.gain(n,40,true)<MapAtmosphereClient.gain(n,40,false),"Wall occlusion reduces source volume");server(p->MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),MapAtmosphere.defaults()));}
            if(age==320){check(!MapAtmosphereClient.settings().getBoolean("enabled"),"Disabling atmosphere restores the shader pack's own presentation");try(var ignored=shot("restored")){}if(Boolean.getBoolean("atmosphere.shaders")){boolean active=false;for(String name:java.util.List.of("net.irisshaders.iris.api.v0.IrisApi","net.coderbot.iris.api.v0.IrisApi")){try{var c=Class.forName(name);Object api=c.getMethod("getInstance").invoke(null);active=(boolean)c.getMethod("isShaderPackInUse").invoke(api);break;}catch(ClassNotFoundException ignored){}}check(active,"A real Oculus shader pack remained active throughout the test");}baseline.close();sky.close();mc.options.hideGui=true;server(p->MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),MapAtmosphere.ashfall()));}
            if(age==330){mc.options.hideGui=false;server(p->{p.getInventory().clearContent();p.teleportTo(p.serverLevel(),.5,65,28.5,180,-65);MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),MapAtmosphere.defaults());});}
            if(age==350){handBaseline=shot("hand-baseline");mc.options.hideGui=true;}
            if(age==360){noHand=shot("no-hand");mc.options.hideGui=false;server(p->MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),neutral()));}
            if(age==395){try(var image=shot("hand-sky")){int pixels=0,preserved=0;for(int y=image.getHeight()/2;y<image.getHeight()-25;y+=2)for(int x=image.getWidth()*2/3;x<image.getWidth()-25;x+=2){int a=handBaseline.getPixelRGBA(x,y),b=noHand.getPixelRGBA(x,y),c=image.getPixelRGBA(x,y);int diff=Math.abs((a&255)-(b&255))+Math.abs((a>>8&255)-(b>>8&255))+Math.abs((a>>16&255)-(b>>16&255));if(diff>65){pixels++;int changed=Math.abs((a&255)-(c&255))+Math.abs((a>>8&255)-(c>>8&255))+Math.abs((a>>16&255)-(c>>16&255));if(changed<55)preserved++;}}System.out.println("ATMOSPHERE HAND PIXELS: "+preserved+" / "+pixels);check(pixels>100,"A visible first-person hand overlaps the sky during the render test");check(preserved>pixels*.9,"Sky compositing preserves the first-person hand silhouette");}handBaseline.close();noHand.close();mc.options.hideGui=true;server(p->{p.teleportTo(p.serverLevel(),.5,65,28.5,180,-14);MapAtmosphere.get(p.serverLevel()).configure(p.serverLevel(),MapAtmosphere.ashfall());});}
            if(age==400){MapAtmosphereClient.receive("preview",neutral());me.cryo.zombierool.client.ClientEnvironmentEffects.setFogPreset("dark",0,0,0,1,12);}
            if(age==405)fogImage=shot("fog-with-sky-enabled");
            if(age==406){var n=neutral();n.putBoolean("skyEnabled",false);MapAtmosphereClient.receive("preview",n);}
            if(age==415){try(var image=shot("fog-with-sky-disabled")){int a=fogImage.getPixelRGBA(800,100),b=image.getPixelRGBA(800,100);int diff=Math.abs((a&255)-(b&255))+Math.abs((a>>8&255)-(b>>8&255))+Math.abs((a>>16&255)-(b>>16&255));check(diff<12,"Active map fog completely suppresses the custom sky pass");}fogImage.close();me.cryo.zombierool.client.ClientEnvironmentEffects.setFogPreset("none",0,0,0,1,512);MapAtmosphereClient.receive("preview",neutral());}
            if(age==425){try(var image=shot("sky-after-fog")){int a=image.getPixelRGBA(800,100);check((a&255)+(a>>8&255)+(a>>16&255)>80,"Custom sky returns automatically when map fog is disabled");}MapAtmosphereClient.receive("preview",MapAtmosphere.ashfall());}
            if(age==430){try(var ignored=shot("showcase")){}done=true;System.out.println("ATMOSPHERE VISUAL PASS: "+checks+" checks");mc.stop();}
        }catch(Throwable t){t.printStackTrace();done=true;System.out.println("ATMOSPHERE VISUAL FAIL: "+t);mc.stop();}
    }
}
